      {
        "command": "arc.removeController",
        "title": "%command.removeController.title%"
      },
      {
        "command": "arc.refresh",
        "title": "%command.refresh.title%"
      },
      {
        "command": "arc.editConnection",
        "title": "%command.editConnection.title%"
      }
