        {
          "command": "arc.openDashboard",
          "when": "view == azureArc && viewItem",
          "group": "navigation@1"
        },
        {
          "command": "arc.editConnection",
          "when": "view == azureArc && viewItem == dataControllers",
          "group": "navigation@2"
        },
        {
          "command": "arc.refresh",
          "when": "view == azureArc && viewItem == dataControllers",
          "group": "navigation@3"
        },
        {
          "command": "arc.removeController",
          "when": "view == azureArc && viewItem == dataControllers",
          "group": "navigation@4"
        }
      ]
