                "label": "%deploy.done.action%"
              },
              "scriptAction": {
                "label": "%deploy.script.action%"
              },
              "codeCellInsertionPosition": 5,
              "title": "%arc.data.controller.new.wizard.title%",
              "name": "arc.data.controller.new.wizard",
              "labelPosition": "left",
