      }
    ],
    "commands": [
      {
        "command": "accounts.clearTokenCache",
        "title": "%accounts.clearTokenCache%",
        "category": "Azure Accounts"
      },
      {
        "command": "azure.resource.signin",
        "title": "%azure.resource.signin.title%",
