                                    },
                                    "color": "red"
                                },
                                {
                                    "condition": {
                                        "if": "equals",
                                        "equals": "Older than 24hrs"
                                    },
                                    "color": "orange"
                                },
                                {
                                    "condition": {
                                        "if": "equals",
                                        "equals": "Within 24hrs"
                                    },
                                    "color": "green"
                                }
                            ]
                        },
                        "value": "Backup_Health",
                        "actions": {
                            "types": [
                                "backup"
                            ],
                            "database": "${Database}"
                        }
                    }
                }
            }
        ]
    }
